#[cfg_attr(
    test,
    allow(
        dead_code,
        reason = "생성된 네이티브 메서드는 테스트 빌드에서 제외됩니다"
    )
)]
impl NativeHyperliquid {
    async fn subscribe_detailed(&self, subscription: maxt::Result<String>) -> Value {
        let subscription = parse_wire::<maxt::Subscription, crate::convert::WireSubscription>(
            subscription,
            "subscription",
        );
        let result = match subscription {
            Ok(subscription) => match self.adapter.subscribe_detailed(&subscription).await {
                Ok(stream) => {
                    self.streams
                        .insert_provider(
                            stream,
                            "hyperliquid_market",
                            crate::stream::provider_stream_item::<
                                maxt::HyperliquidMarketEvent,
                                crate::convert::WireHyperliquidMarketEvent,
                            >,
                        )
                        .await
                }
                Err(error) => Err(error),
            },
            Err(error) => Err(error),
        };
        outcome(result)
    }

    async fn subscribe_detailed_with(
        &self,
        subscription: maxt::Result<String>,
        config: maxt::Result<String>,
    ) -> Value {
        let subscription = parse_wire::<maxt::Subscription, crate::convert::WireSubscription>(
            subscription,
            "subscription",
        );
        let config =
            parse_wire::<maxt::StreamConfig, crate::convert::WireStreamConfig>(config, "config");
        let result = match (subscription, config) {
            (Ok(subscription), Ok(config)) => match self
                .adapter
                .subscribe_detailed_with(&subscription, &config)
                .await
            {
                Ok(stream) => {
                    self.streams
                        .insert_provider(
                            stream,
                            "hyperliquid_market",
                            crate::stream::provider_stream_item::<
                                maxt::HyperliquidMarketEvent,
                                crate::convert::WireHyperliquidMarketEvent,
                            >,
                        )
                        .await
                }
                Err(error) => Err(error),
            },
            (Err(error), _) => Err(error),
            (_, Err(error)) => Err(error),
        };
        outcome(result)
    }

    async fn subscribe_detailed_account(&self) -> Value {
        outcome(match self.adapter.subscribe_detailed_account().await {
            Ok(stream) => {
                self.streams
                    .insert_provider(
                        stream,
                        "hyperliquid_account",
                        crate::stream::provider_stream_item::<
                            maxt::HyperliquidAccountEvent,
                            crate::convert::WireHyperliquidAccountEvent,
                        >,
                    )
                    .await
            }
            Err(error) => Err(error),
        })
    }

    async fn subscribe_detailed_account_with(&self, config: maxt::Result<String>) -> Value {
        let config =
            parse_wire::<maxt::StreamConfig, crate::convert::WireStreamConfig>(config, "config");
        let result = match config {
            Ok(config) => match self.adapter.subscribe_detailed_account_with(&config).await {
                Ok(stream) => {
                    self.streams
                        .insert_provider(
                            stream,
                            "hyperliquid_account",
                            crate::stream::provider_stream_item::<
                                maxt::HyperliquidAccountEvent,
                                crate::convert::WireHyperliquidAccountEvent,
                            >,
                        )
                        .await
                }
                Err(error) => Err(error),
            },
            Err(error) => Err(error),
        };
        outcome(result)
    }

    async fn all_mids_detail(&self) -> Value {
        outcome(
            self.adapter
                .all_mids_detail()
                .await
                .and_then(TryInto::<crate::convert::WireHyperliquidAllMids>::try_into),
        )
    }

    async fn perpetual_meta(&self) -> Value {
        outcome(
            self.adapter
                .perpetual_meta()
                .await
                .and_then(TryInto::<crate::convert::WireHyperliquidProviderResponse>::try_into),
        )
    }

    async fn perpetual_meta_and_asset_contexts(&self) -> Value {
        outcome(
            self.adapter
                .perpetual_meta_and_asset_contexts()
                .await
                .and_then(TryInto::<crate::convert::WireHyperliquidProviderResponse>::try_into),
        )
    }

    async fn clearinghouse_state_detail(&self) -> Value {
        outcome(
            self.adapter
                .clearinghouse_state_detail()
                .await
                .and_then(TryInto::<crate::convert::WireHyperliquidProviderResponse>::try_into),
        )
    }

    async fn frontend_open_orders_detail(&self) -> Value {
        outcome(
            self.adapter
                .frontend_open_orders_detail()
                .await
                .and_then(TryInto::<crate::convert::WireHyperliquidProviderResponse>::try_into),
        )
    }

    async fn place_order_detail(&self, request: maxt::Result<String>) -> Value {
        let request =
            parse_wire::<maxt::OrderRequest, crate::convert::WireOrderRequest>(request, "request");
        let result =
            match request {
                Ok(request) => self.adapter.place_order_detail(&request).await.and_then(
                    TryInto::<crate::convert::WireHyperliquidOrderActionResponse>::try_into,
                ),
                Err(error) => Err(error),
            };
        outcome(result)
    }

    async fn cancel_order_detail(
        &self,
        market: maxt::Result<String>,
        order_id: maxt::Result<String>,
    ) -> Value {
        let market = parse_wire::<maxt::Market, crate::convert::WireMarket>(market, "market");
        let order_id = parse_text::<String>(order_id, "orderId");
        let result = match (market, order_id) {
            (Ok(market), Ok(order_id)) => self
                .adapter
                .cancel_order_detail(&market, &order_id)
                .await
                .and_then(TryInto::<crate::convert::WireHyperliquidProviderResponse>::try_into),
            (Err(error), _) => Err(error),
            (_, Err(error)) => Err(error),
        };
        outcome(result)
    }

    async fn stream_next(&self, id: maxt::Result<String>) -> Value {
        let result = match parse_text::<String>(id, "stream_id") {
            Ok(id) => self.streams.next(&id).await,
            Err(error) => Err(error),
        };
        outcome(result)
    }

    async fn stream_close(&self, id: maxt::Result<String>) -> Value {
        let result = match parse_text::<String>(id, "stream_id") {
            Ok(id) => self.streams.close(&id).await,
            Err(error) => Err(error),
        };
        outcome(result.map(|()| Value::Null))
    }
}

